import sys
import xml.etree.ElementTree as ET
import json

def parse_xml_to_dict(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    result = {}

    for item in root.findall('item'):
        name = item.get('name')
        value_str = item.get('value')
        type_ = item.get('type')

        if type_ == 'int':
            try:
                value = int(value_str)
            except ValueError:
                continue
        elif type_ == 'float':
            try:
                value = float(value_str)
            except ValueError:
                continue
        elif type_ == 'bool':
            if value_str.lower() == 'true':
                value = True
            elif value_str.lower() == 'false':
                value = False
            else:
                continue
        elif type_ == 'string':
            value = value_str
        else:
            continue

        result[name] = value

    return result

def main():
    xml_path = sys.stdin.readline().strip()
    config_dict = parse_xml_to_dict(xml_path)
    sorted_keys = sorted(config_dict.keys())
    output = json.dumps({k: config_dict[k] for k in sorted_keys}, separators=(',', ':'))

    print(output)

if __name__ == "__main__":
    main()
